import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The chessboard","description":"","frontmatter":{},"headers":[],"params":{"slug":"chess","address":"e164a960-f259-8565-af24-c27c38571053","receipt":"f1cb69d7-b95c-84d1-82f9-6636b2ac6408"},"relativePath":"docs/publications/chess.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/chess.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-chessboard" tabindex="-1">The chessboard <a class="header-anchor" href="#the-chessboard" aria-label="Permalink to “The chessboard”">​</a></h1><blockquote><p>chess geometry as decidable arithmetic — the board is 8×8 = 64 = 2⁶ squares in two colours of 32 each ((rank+file) parity); the knight leaps 1+2=3 (odd), so it flips colour every move and a closed tour is even; the rook reaches 7+7=14 on an open board; the bishop preserves colour, forever closed out of half the board; and the queen is rook+bishop, 7+7+7=21 from a corner — board arithmetic and parity, NOT a solved game or an engine</p></blockquote><p>These 8 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>The board is 8×8 = 64 = 2⁶ squares — the same 64 the whole project is tuned to (six doublings, the bit measure). — <a href="/theorem/chessboard_sixty_four">proof</a>.</li><li>Exactly 32 squares of each colour: the colour is the (rank+file) parity, and half of the 64 squares are even — a balanced 2-colouring, 32 light and 32 dark. — <a href="/theorem/chessboard_two_colours">proof</a>.</li><li>The knight leaps 1+2 = 3 squares (Manhattan), which is ODD — so every knight move changes the (rank+file) parity, i.e. it flips the square colour. White-square knight → black square, always. — <a href="/theorem/knight_leap_is_odd">proof</a>.</li><li>A knight has exactly 8 moves — the eight (±1,±2) and (±2,±1) offsets. From the centre all 8 are on the board; from a corner only 2 are. — <a href="/theorem/knight_has_eight_moves">proof</a>.</li><li>Because a knight flips colour every move, it returns to its start colour only after an EVEN number of moves — so a closed knight’s tour has even length, and the full-board tour is 64 (even). 64 % 2 = 0. — <a href="/theorem/closed_knight_tour_even">proof</a>.</li><li>A rook on an otherwise-empty board attacks 14 squares — 7 along its rank and 7 along its file (all but its own), independent of where it stands. 7+7 = 14. — <a href="/theorem/rook_open_board_fourteen">proof</a>.</li><li>A bishop moves (±1,±1), and 1+1 = 2 is EVEN — so it preserves the (rank+file) parity and never changes square colour. A light-squared bishop can never reach the 32 dark squares: half the board is forever closed to it. — <a href="/theorem/bishop_stays_on_colour">proof</a>.</li><li>The queen is rook + bishop: from a corner of an open board she reaches 7 (rank) + 7 (file) + 7 (long diagonal) = 21 squares — the same 21 = 3×7 the trinity and the rosette fold to. — <a href="/theorem/queen_corner_twentyone">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 8 proofs fold, order-invariant, to the receipt <code>f1cb69d7-b95c-84d1-82f9-6636b2ac6408</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Chess.lean" target="_blank" rel="noreferrer">lean/Chess.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>e164a960</code> · proofs fold to receipt <code>f1cb69d7</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 8 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};